ALTER TABLE public.ads ADD COLUMN IF NOT EXISTS video_url text, ADD COLUMN IF NOT EXISTS thumbnail_url text, ADD COLUMN IF NOT EXISTS is_video boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS scheduled_for timestamptz, ADD COLUMN IF NOT EXISTS recurrence_rule jsonb, ADD COLUMN IF NOT EXISTS is_recurring boolean NOT NULL DEFAULT false;
ALTER TABLE public.marketing_ads ADD COLUMN IF NOT EXISTS type text DEFAULT 'marketing', ADD COLUMN IF NOT EXISTS caption text, ADD COLUMN IF NOT EXISTS hashtags text, ADD COLUMN IF NOT EXISTS product_name text, ADD COLUMN IF NOT EXISTS prompt_used text, ADD COLUMN IF NOT EXISTS video_url text, ADD COLUMN IF NOT EXISTS audio_url text, ADD COLUMN IF NOT EXISTS voice_url text, ADD COLUMN IF NOT EXISTS thumbnail_url text, ADD COLUMN IF NOT EXISTS link_url text, ADD COLUMN IF NOT EXISTS call_to_action text DEFAULT 'Learn More', ADD COLUMN IF NOT EXISTS is_paid boolean DEFAULT false, ADD COLUMN IF NOT EXISTS publish_at timestamptz, ADD COLUMN IF NOT EXISTS published_at timestamptz, ADD COLUMN IF NOT EXISTS scheduled_for timestamptz, ADD COLUMN IF NOT EXISTS is_recurring boolean DEFAULT false, ADD COLUMN IF NOT EXISTS recurrence_rule jsonb, ADD COLUMN IF NOT EXISTS is_web_ad boolean DEFAULT false, ADD COLUMN IF NOT EXISTS analytics jsonb DEFAULT '{}'::jsonb;
ALTER TABLE public.scheduled_ads ADD COLUMN IF NOT EXISTS web_ad_id uuid REFERENCES public.ads(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS recurrence text DEFAULT 'once', ADD COLUMN IF NOT EXISTS is_recurring boolean DEFAULT false, ADD COLUMN IF NOT EXISTS recurrence_rule jsonb, ADD COLUMN IF NOT EXISTS created_by text DEFAULT 'partner';
CREATE TABLE IF NOT EXISTS public.platforms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, slug text, icon_url text, description text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.platforms TO service_role;
ALTER TABLE public.platforms ENABLE ROW LEVEL SECURITY;